        /* 关于页 */
        "about.banner.title": "公司介绍",
        "about.profile.eyebrow": "Company Profile / 公司简介",
        "about.profile.title": "专注品质 · 缔造塑胶地板行业标杆",
        "about.profile.p1": "东阳茂盛塑胶有限公司（DONGYANG MAOSHENG PLASTIC CO.,LTD）成立于 2006 年，总部位于浙江省东阳市横店工业区科兴路 17 号，毗邻世界小商品贸易之都——义乌，距义乌仅 30 公里，区位优势显著，物流网络发达。",
        "about.profile.p2": "公司集塑胶地板研发、生产、销售于一体，主营产品涵盖干背式胶粘、锁扣式、免胶铺装三大系列，凭借完整的分类体系、庞大的年产量、超群的品质与全球出口能力，深受海内外客户信赖。2015 年 8 月第二工厂竣工投产，厂区总面积扩展至 8.24 英亩，年销售额突破 1600 万美元。",
        "about.profile.p3": "我们的产品已远销欧洲、南美、北美、中美、拉丁美洲、非洲及东南亚等 30 多个国家和地区，是众多国际采购商的长期合作伙伴。",
        "about.profile.btn": "联系合作",
        "about.stats.years": "深耕行业经验", "about.stats.factories": "现代化工厂",
        "about.stats.factoriesUnit": "座", "about.stats.sales": "年销售额突破", "about.stats.countries": "出口国家与地区",
        "about.stats.yearsUnit": "年", "about.stats.salesUnit": "万 USD", "about.stats.countriesUnit": "+",
        "about.badge.label": "英亩厂区面积",
        "about.history.eyebrow": "Our History", "about.history.title": "发展历程",
        "about.history.lead": "十九年砥砺前行，茂盛塑胶始终专注于塑胶地板制造，一步一个脚印，铸就行业口碑。",
        "about.t1.y": "2006", "about.t1.t": "公司成立", "about.t1.d": "东阳茂盛塑胶有限公司在浙江东阳横店工业区正式创立，开启塑胶地板制造之路。",
        "about.t2.y": "2006-2014", "about.t2.t": "深耕发展", "about.t2.d": "持续优化生产工艺与产品线，逐步建立覆盖干背式、锁扣式、免胶铺装三大系列的产品体系。",
        "about.t3.y": "2015", "about.t3.t": "通过 DIBT 认证", "about.t3.d": "产品通过德国 DIBT 认证，品质达到国际标准，为公司进军高端海外市场奠定坚实基础。",
        "about.t4.y": "2015.08", "about.t4.t": "第二工厂竣工", "about.t4.d": "公司第二工厂建成投产，厂区总面积扩展至 8.24 英亩，日产能大幅提升，满足全球订单需求。",
        "about.t5.y": "2015", "about.t5.t": "销售突破千万美元", "about.t5.d": "公司年总销售额达到 1600 万美元，产品出口至欧洲、美洲、非洲、东南亚等全球市场。",
        "about.t6.y": "2018-2019", "about.t6.t": "亮相国际展会", "about.t6.d": "连续参展上海 Domotex 地材展、美国拉斯维加斯 SURFACES 展，品牌国际影响力持续提升。",
        "about.t7.y": "2026", "about.t7.t": "持续创新", "about.t7.d": "秉承匠心精神，深化产品研发与工艺升级，致力于为全球客户提供更优质的塑胶地板解决方案。",
        "about.strength.eyebrow": "Our Strength", "about.strength.title": "企业核心实力",
        "about.strength.lead": "完善的产业链、强大的产能与严苛的品质管控，是茂盛持续赢得市场的根基。",
        "about.s1.t": "完整产品分类", "about.s1.d": "覆盖干背式、锁扣式、免胶铺装三大安装工艺，木纹、石纹、深压纹多款花色，规格厚度可柔性定制，一站式满足多样化采购需求。",
        "about.s2.t": "庞大年产能力", "about.s2.d": "双工厂协同生产，8.24 英亩现代化厂区，日产能充足稳定，可从容应对大宗海外订单与紧急加单需求。",
        "about.s3.t": "超群品质保障", "about.s3.d": "严选再生/原包浆 PVC 原料，2015 年通过德国 DIBT 认证，从原料到成品层层质检，确保每一片地板达到国际标准。",
        "about.s4.t": "全球出口网络", "about.s4.d": "产品远销欧洲、北美、南美、中美、拉丁美洲、非洲、东南亚等 30 多个国家和地区，拥有成熟的国际物流与清关经验。",
        "about.s5.t": "区位物流优势", "about.s5.d": "地处浙江东阳横店工业区，距义乌仅 30 公里，紧邻世界小商品贸易之都，物流网络四通八达，发货高效便捷。",
        "about.s6.t": "国际展会背书", "about.s6.d": "连续参展上海 Domotex、拉斯维加斯 SURFACES 等国际顶级地材展会，与全球行业伙伴保持紧密交流与合作。",
        "about.cert.eyebrow": "Certifications", "about.cert.title": "行业资质与认证",
        "about.cert.lead": "权威认证是对茂盛品质的最佳背书，也是客户信赖的坚实保障。",
        "about.cert1.t": "DIBT 认证", "about.cert1.d": "德国建筑技术研究所认证，2015 年通过，符合欧洲高端市场准入标准。",
        "about.cert2.t": "ISO 质量管理", "about.cert2.d": "ISO 9001 质量管理体系，从原料到成品的全流程标准化管控。",
        "about.cert3.t": "防火性能认证", "about.cert3.d": "通过权威防火检测，达到建筑材料防火安全标准，使用更安心。",
        "about.cert4.t": "CE 欧盟认证", "about.cert4.d": "符合欧盟 CE 标准，满足欧洲对建材健康、安全与环保的强制性要求。",
        "about.cert.note": "* 以上为代表性认证，更多资质证明资料可向客服索取，以实际证书文件为准。",
        "about.factory.eyebrow": "Factory Gallery", "about.factory.title": "工厂与生产实况",
        "about.factory.lead": "现代化的生产车间与仓储物流体系，保障每一笔订单的稳定交付。",
        "about.cta.title": "期待与您携手，共创长远合作",
        "about.cta.desc": "欢迎实地考察工厂，或在线联系获取详细产品资料与报价方案。",
        "about.cta.btn1": "联系我们", "about.cta.btn2": "浏览产品",

