        "index.about.p1": "تأسست شركة Dongyang Maosheng Plastic Co., Ltd. عام 2006 في هينغديان، دونغيانغ، تشجيانغ، بالقرب من ييوو — عاصمة تجارة السلع الصغيرة عالمياً — بموقع متميز ولوجستيات مريحة.",
        "index.about.p2": "في عام 2015 حصلنا على شهادة DIBT. في العام نفسه، اكتمل المصنع الثاني، مما وسّع المساحة الإجمالية إلى 8.24 فدان، مع مبيعات سنوية تجاوزت 16 مليون دولار. التصدير إلى أكثر من 30 دولة.",
